// Translation-only, low resolution global motion. No optical-flow warping.
export function translation(a,b,n=48){let best=Infinity,second=Infinity,bx=0,by=0;for(let dy=-4;dy<=4;dy++)for(let dx=-4;dx<=4;dx++){let cost=0,count=0;for(let y=7;y<n-7;y+=2)for(let x=7;x<n-7;x+=2){cost+=Math.min(40,Math.abs(a[y*n+x]-b[(y+dy)*n+x+dx]));count++}cost/=count;if(cost<best){second=best;best=cost;bx=dx;by=dy}else second=Math.min(second,cost)}return best>28||second-best<.02?[0,0]:[bx/n,by/n];}
export function smoothPath(points,strength){const radius={WEAK:2,HANDHELD:2,MEDIUM:5,NATURAL:5,STRONG:10,GIMBAL:10,TRIPOD:18}[strength]||5;const px=[0],py=[0];for(const p of points){px.push(px.at(-1)+p.x);py.push(py.at(-1)+p.y)}let max=0;const result=points.map((p,i)=>{const a=Math.max(0,i-radius),b=Math.min(points.length,i+radius+1);const x=Math.max(-.08,Math.min(.08,(px[b]-px[a])/(b-a)-p.x)),y=Math.max(-.08,Math.min(.08,(py[b]-py[a])/(b-a)-p.y));max=Math.max(max,Math.abs(x),Math.abs(y));return{time:p.time,x,y}});return{points:result,scale:1+2*max+.015,crop:1-1/(1+2*max+.015)};}
export function correctionAt(path,t){const p=path.points;if(!p.length)return{x:0,y:0};let lo=0,hi=p.length-1;while(lo<hi){const mid=Math.ceil((lo+hi)/2);if(p[mid].time<=t)lo=mid;else hi=mid-1}const a=p[lo],b=p[Math.min(lo+1,p.length-1)],f=b.time>a.time?Math.max(0,Math.min(1,(t-a.time)/(b.time-a.time))):0;return{x:a.x+(b.x-a.x)*f,y:a.y+(b.y-a.y)*f};}
